  [1219010] = { "Riduce di $D1 il tempo di recupero di ⟦Lay on Hands=Mano Celestiale⟧, e ora ⟦Lay on Hands=Mano Celestiale⟧, quando viene usata, ti riporta al $N2% del mana massimo.", nil, 0x1f3caf15, nil, "um" },
  [1219019] = { "Gli effetti periodici d'ombra hanno una probabilità di applicare Creeping Darkness, fino a $N1 volte. Gli incantesimi che infliggono danni diretti da ombra fanno detonare l'effetto, infliggendo $N2 danni per accumulo.", nil, 0x78689b68, nil, "um" },
  [1219020] = { "Gli effetti periodici d'ombra hanno una probabilità di applicare Creeping Darkness, fino a $N1 volte. Gli incantesimi che infliggono danni diretti da ombra fanno detonare l'effetto, infliggendo $N2 danni per accumulo.", "L'oscurità comincia a circondarti, infliggendo inevitabilmente $N1 danni da ombra.", 0x731b4d64, 0x068cef3a, "uu" },
  [1219024] = { "Gli effetti periodici d'ombra hanno una probabilità di applicare Creeping Darkness, fino a $N1 volte. Gli incantesimi che infliggono danni diretti da ombra fanno detonare l'effetto, infliggendo $N2 danni per accumulo.", nil, 0x731b4d64, nil, "um" },
  [1219043] = { "Fracassa il cadavere di un amico o di un nemico caduto, infliggendo $N1 danni ai nemici vicini.", nil, 0xea582ef9, nil, "um" },
