  [1219260] = { "Imboscata e ⟦Instant Poison=Veleno Istantaneo⟧ infliggono il $N1% di danni in più. Pugnalata alle Spalle infligge il $N2% di danni in più (non vale per Mutilazione). Ti curi del $N3% di tutti i danni inflitti dai tuoi veleni.", nil, 0x2081b078, nil, "um" },
