  [1219503] = { "Riduce del $N1% le tue dimensioni e la minaccia che generi per $D1.", "Dimensioni e minaccia generata ridotte del $N1%.", 0xf1bbff24, 0xce0fe7d9, "uu" },
  [1219506] = { "Rigenera $N1 mana.", nil, 0x09fdd6de, nil, "um" },
  [1219507] = { "Aggiunge in modo permanente a un oggetto per le spalle un aumento fino a $N1 delle cure prodotte da incantesimi ed effetti magici, e aumenta inoltre la rigenerazione del mana di $N2 mana ogni $D1.", nil, 0xddab39b3, nil, "um" },
  [1219510] = { "Aggiunge in modo permanente a un oggetto per le spalle un aumento fino a $N1 dei danni e delle cure prodotti da incantesimi ed effetti magici, e aumenta inoltre del $N2% la probabilità di infliggere un colpo critico.", nil, 0x314de3bd, nil, "um" },
  [1219511] = { "Aggiunge in modo permanente a un oggetto per le spalle un aumento della Tempra di $N1 e della Difesa di $N2.", nil, 0x54c249bc, nil, "um" },
  [1219512] = { "Aggiunge in modo permanente a un oggetto per le spalle un aumento della potenza d'attacco di $N1, e aumenta inoltre del $N2% la probabilità di infliggere un colpo critico.", nil, 0x811e608c, nil, "um" },
  [1219513] = { "Aumenta fino a $N2 le cure prodotte dai prossimi $N1 incantesimi per $D1.", "Incantesimi di cura aumentati fino a $N1.", 0x9695f8e3, 0xd754af7b, "uu" },
  [1219515] = { "Aumenta fino a $N1 i danni e le cure di incantesimi ed effetti magici per $D1.", "Danni e cure degli incantesimi aumentati fino a $N1.", 0xc0d35181, 0xce30f511, "uu" },
  [1219519] = { "Aumenta la potenza d'attacco di $N1 per $D1.", "Potenza d'attacco aumentata di $N1.", 0xb593685a, 0x2905f15b, "uu" },
  [1219520] = { "Aumenta di $N1 l'indice di blocco dello scudo per $D1.", "Indice di blocco aumentato di $N1.", 0xe7882b6e, 0x64e8286f, "uu" },
  [1219521] = { "+$N1 potenza d'attacco contro Non Morti e demoni. Permette inoltre di ottenere Pietre del Flagello per conto dell'⟦Argent Dawn=Alba d'Argento⟧.", nil, 0xdbacf565, nil, "um" },
  [1219522] = { "Aumenta fino a $N1 i danni inflitti a Non Morti e Demoni da incantesimi ed effetti magici. Permette di ottenere le Pietre del Flagello per conto dell'⟦Argent Dawn=Alba d'Argento⟧.", nil, 0xc1a76244, nil, "um" },
  [1219539] = { "Libera il tuo potenziale all'interno di Naxxramas, aumentando i tuoi danni del $N1% e la tua salute del $N2% per ogni oggetto Consacrato indossato. (Indossare più di $N3 oggetti Consacrati non dà alcun beneficio aggiuntivo)", "Libera il tuo potenziale all'interno di Naxxramas, aumentando i tuoi danni del $N1% e la tua salute del $N2% per ogni oggetto Consacrato indossato.", 0x239ff9c8, 0xc451f1c1, "uu" },
  [1219540] = { "Provocazione non manca mai il bersaglio, e la probabilità che venga schivata o parata è ridotta del $N1%.", nil, 0xd243841f, nil, "um" },
  [1219541] = { "Costringe il bersaglio ad attaccarti, ma non ha effetto se il bersaglio ti sta già attaccando.", nil, 0x71de38fd, nil, "um" },
  [1219543] = { "Riduce di $D1 il tempo di recupero di ⟦Shield Wall=Muro di Scudi⟧ e di $D2 quello di Avventatezza. Avventatezza ora può essere usata in qualsiasi postura e non aumenta i danni subiti.", nil, 0x4c47736c, nil, "um" },
  [1219544] = { "Quando subisci danni da un nemico Non Morto, la durata rimanente di ⟦Last Stand=Ultima Difesa⟧ attiva torna a $D1.", nil, 0xbef9d539, nil, "um" },
  [1219548] = { "Libera il tuo potenziale all'interno di Naxxramas, aumentando le tue cure del $N1% e la tua salute del $N2% per ogni oggetto Consacrato indossato. (Indossare più di $N3 oggetti Consacrati non dà alcun beneficio aggiuntivo)", "Libera il tuo potenziale all'interno di Naxxramas, aumentando le tue cure del $N1% e la tua salute del $N2% per ogni oggetto Consacrato indossato.", 0xfb50752c, 0x3a3efb98, "uu" },
  [1219552] = { "Aumenta fino a $N2 i danni e le cure prodotti da incantesimi ed effetti magici di tutti i membri del gruppo entro $N1 m. Questo effetto specifico non è cumulabile da più fonti.", "Aumenta fino a $N1 i danni e le cure prodotti da incantesimi ed effetti magici. Questo effetto specifico non è cumulabile da più fonti.", 0x0c3354b0, 0xc9de4c90, "uu" },
  [1219553] = { "Aumenta fino a $N1 le cure prodotte e fino a $N2 i danni inflitti da tutti gli incantesimi ed effetti magici di tutti i membri del gruppo entro $N3 m. Questo effetto specifico non è cumulabile da più fonti.", "Aumenta fino a $N1 le cure prodotte e fino a $N2 i danni inflitti da tutti gli incantesimi ed effetti magici. Questo effetto specifico non è cumulabile da più fonti.", 0x828eded3, 0x0de1dc02, "uu" },
  [1219557] = { nil, "Aumenta del $N1% la velocità di lancio degli incantesimi. Questo effetto specifico non è cumulabile da più fonti.", nil, 0x05f89473, "mu" },
  [1219558] = { nil, "Aumenta del $N2% la probabilità di critico con gli incantesimi di tutti i membri del gruppo entro $N1 m. Questo effetto specifico non è cumulabile da più fonti.", nil, 0x0490bbea, "mu" },
  [1219706] = { nil, "$N1 energia rigenerata.", nil, 0x4f24baef, "mu" },
  [1219707] = { nil, "$N1 rabbia generata.", nil, 0x562c792a, "mu" },
  [1219708] = { "Rigenera $N1 mana.", "$N1 mana rigenerato.", 0x09fdd6de, 0xffb4963e, "uu" },
  [1219729] = { nil, "Subisci ingenti danni da gelo quando questa aura scade, ripartiti tra tutti gli alleati vicini.", nil, 0xa9c281f1, "mu" },
  [1219732] = { nil, "Subisci ingenti danni da gelo quando questa aura scade, ripartiti tra tutti gli alleati vicini.", nil, 0xa9c281f1, "mu" },
  [1219741] = { nil, "Infligge $N1 danni da ombra ogni $D1. Velocità di movimento ridotta del $N3%.", nil, 0x74a97ae9, "mu" },
  [1219821] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Kineticist:\n\nI tuoi danni periodici hanno il $N1% di probabilità di azzerare il tempo di recupero di una delle tue abilità di assalto. Viene sempre scelto l'assalto con il tempo di recupero residuo più lungo.", nil, 0x7f1ab835, nil, "um" },
  [1219822] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Strategist:\n\nAumenta del $N1% i danni periodici di Wyvern Strike e di $N2 il Focus massimo del tuo famiglio.", nil, 0x168d3e9c, nil, "um" },
  [1219823] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Deadly Striker:\n\nAumenta del $N1% i danni dell'impatto di Morso della Mangusta e di tutte le abilità di assalto.", nil, 0xd5fad7da, nil, "um" },
  [1219824] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Hastened Healer:\n\n-$D1 al tempo di lancio di Cura Rapida e -$D2 al tempo di lancio di Cura Maggiore.", nil, 0x9ab400ed, nil, "um" },
  [1219826] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Celebrant:\n\nAumenta del $N1% la tua probabilità di critico con Preghiera di Cura e Circolo di Guarigione.", nil, 0x710f3501, nil, "um" },
  [1219827] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Faithful:\n\nPermette al $N1% della rigenerazione del mana di continuare durante il lancio di incantesimi.", nil, 0x0830d48d, nil, "um" },
  [1219828] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Serendipitous:\n\nLe tue cure periodiche hanno una probabilità del $N1% di rendere istantaneo il tuo prossimo incantesimo con un tempo di lancio inferiore a $N2 s.", nil, 0x24bd33e1, nil, "um" },
  [1219829] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Resonant:\n\nCircolo di Guarigione e Contrizione applicano anche ai loro bersagli un effetto di cura periodica che cura del $N1% di tale quantità in $D1.", nil, 0xb78e45a1, nil, "um" },
  [1219830] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Devotee:\n\nLa tua Preghiera di Guarigione ottiene $N1 cariche aggiuntive.", nil, 0xe02e70d2, nil, "um" },
  [1219831] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Archbishop:\n\nIl tuo Circolo di Guarigione ora cura il membro più ferito del gruppo bersaglio del $N1% in più.", nil, 0x6a8a1a27, nil, "um" },
  [1219832] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Penitent:\n\nRiduce il tempo di recupero di Contrizione di $D1.", nil, 0x9d26bb1c, nil, "um" },
  [1219833] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Soul Warder:\n\nAumenta del $N1% i danni assorbiti dal tuo incantesimo Parola del Potere: Scudo.", nil, 0xcd0b1c0f, nil, "um" },
  [1219834] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Twilight Walker:\n\nPuoi lanciare Cura Rapida in Forma d'Ombra.", nil, 0xddccd53e, nil, "um" },
  [1219835] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Mind Breaker:\n\nI colpi critici di Detonazione Mentale riducono del $N1% la durata del tuo prossimo Flagello Mentale, aumentandone del $N2% i danni totali.", nil, 0xd3ce0447, nil, "um" },
  [1219836] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Deathdealer:\n\nRiduce il tempo di recupero di Parola d'Ombra: Morte di $D1.", nil, 0x85a70d75, nil, "um" },
  [1219837] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Spirit Font:\n\nLa tua Parola d'Ombra: Dolore ha una probabilità del $N1% per punto talento in Spirit Tap di attivare il tuo talento Spirit Tap quando infligge danni, o del $N2% per punto talento quando un bersaglio muore con la tua Parola d'Ombra: Dolore attiva. Anche Concentrazione Interiore ha una probabilità del $N3% per punto talento di attivare Spirit Tap.", nil, 0xc60a4683, nil, "um" },
  [1219838] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Zealot:\n\nMentre Spirit Tap è attivo, infliggi il $N1% di danni da ombra in più.", nil, 0x67a3a9a3, nil, "um" },
  [1219839] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Unwavering Defiler:\n\nIl tuo Flagello Mentale non perde più durata quando subisci danni e, al lancio, scaglia sul bersaglio un Aculeo Mentale gratuito.", nil, 0xd3d17c8f, nil, "um" },
  [1219840] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Contemnor:\n\nIl tuo Aculeo Mentale ora è istantaneo, infligge il $N1% di danni in più e può essere lanciato mentre canalizzi un altro incantesimo.", nil, 0xf37bd08a, nil, "um" },
  [1219841] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Plaguebringer:\n\nLa tua runa Dolore e Sofferenza ora può rinnovare la durata di Piaga Divoratrice.", nil, 0x05886fbb, nil, "um" },
  [1219842] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Reverberant:\n\nI tuoi Temporal Beacon durano il $N1% in più.", nil, 0x309939fb, nil, "um" },
  [1219843] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Chronohealer:\n\nAumenta del $N1% tutte le cure cronomantiche che effettui.", nil, 0x38053f49, nil, "um" },
  [1219844] = { "Infondi in modo permanente nei tuoi spallacci la Soul of Temporal Longing:\n\nOgni volta che curi un bersaglio con Rigenerazione, il tempo di recupero rimanente di Riavvolgimento Temporale si riduce di $D1.", nil, 0xb93c079f, nil, "um" },
  [1219845] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Precognitive:\n\nI tuoi Missili Arcani restituiscono il $N1% del loro costo base in mana ogni volta che infliggono danni.", nil, 0xed6e9d75, nil, "um" },
  [1219846] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Arcanist:\n\nDetonazione Arcana ottiene una probabilità aggiuntiva del $N1% di attivare Raffica di Missili, e Raffica di Missili ora influisce su Rigenerazione come su Missili Arcani.", nil, 0xed8c7d34, nil, "um" },
  [1219847] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Eternal Caretaker:\n\nI tuoi Temporal Beacon applicati da Rigenerazione di Massa ora durano $D1.", nil, 0x93607967, nil, "um" },
  [1219848] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Spellbider:\n\nLa tua Detonazione Arcana aumenta i danni inflitti di un ulteriore $N1% per accumulo.", nil, 0x84091821, nil, "um" },
  [1219849] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Wardshaper:\n\nScudo di Mana, Guardia di Fuoco e Protezione dal Gelo assorbono il $N1% di danni in più e applicano anche Temporal Beacon al bersaglio per $D1.", nil, 0xf08d0200, nil, "um" },
  [1219850] = { "Infondi in modo permanente nei tuoi spallacci la Soul of Winter's Grasp:\n\nAumenta di un ulteriore $N1% la probabilità di attivare la tua runa Dita di Gelo.", nil, 0x4ea4cb97, nil, "um" },
  [1219851] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Cryomancer:\n\nAumenta del $N1% i danni inflitti dai tuoi incantesimi Dardo di Gelo e Dardo di Geloincanto.", nil, 0xa97bced4, nil, "um" },
  [1219852] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Evoker:\n\nSei immune a tutti i danni mentre canalizzi Evocazione.", nil, 0xb8a6b955, nil, "um" },
  [1219853] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Elementalist:\n\nOttieni il $N1% di danni in più per $D1 ogni volta che lanci un incantesimo di una scuola di magia diversa.", nil, 0x5ab56f0c, nil, "um" },
  [1219854] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Magical Armorer:\n\nArmatura Magica aumenta di un ulteriore $N1% la tua rigenerazione del mana durante il lancio. Armatura Lavica aumenta di $N2 i tuoi danni magici e le tue cure. Armatura di Ghiaccio aumenta del $N3% la probabilità di attivare Dita di Gelo.", nil, 0xd484e42d, nil, "um" },
  [1219855] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Kindler:\n\nRiduce del $N1% la minaccia generata dai tuoi incantesimi di fuoco.", nil, 0xc429d5b8, nil, "um" },
  [1219856] = { "Infondi in modo permanente nei tuoi spallacci la Soul of Fiery Convergence:\n\nLa tua Pirosfera infligge il $N1% di danni in più ai bersagli colpiti dall'effetto periodico della tua Palla di Fuoco.", nil, 0x42ed8f92, nil, "um" },
  [1219857] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Perpetual Blaze:\n\nL'effetto periodico della tua Palla di Fuoco infligge danni aggiuntivi nell'arco della sua durata pari al $N1% dei danni dell'impatto.", nil, 0xbb4a5dbb, nil, "um" },
  [1219858] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Pyromaniac:\n\nLa tua Detonazione di Fuoco ora aumenta anche del $N1% la probabilità di critico del tuo prossimo incantesimo di fuoco per $D1.", nil, 0x7087ef35, nil, "um" },
  [1219859] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Igniter:\n\nAumenta del $N1% i danni inflitti dal tuo talento Incendio.", nil, 0x00814fae, nil, "um" },
  [1219860] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Torcher:\n\nI tuoi incantesimi Palla di Fuoco, Palla di Fuocogelo e Balefire Bolt infliggono il $N1% di danni in più per ognuno dei tuoi effetti di fuoco sul bersaglio, fino a un massimo del $N2%.", nil, 0x8eec4150, nil, "um" },
  [1219862] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Lightwarden:\n\nTi curi di $N1 quando blocchi. La cura può avvenire solo una volta ogni pochi secondi.", nil, 0x76f4d5d7, nil, "um" },
  [1219863] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Radiant Defender:\n\nScudo Benedetto non ha più cariche e dura sempre per tutta la sua durata. Inoltre, i suoi danni aumentano del $N1% del tuo indice di blocco con lo scudo.", nil, 0x7eefa41c, nil, "um" },
  [1219864] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Shieldbearer:\n\nAumenta del $N1% la probabilità di blocco aggiuntiva conferita da Scudo Benedetto.", nil, 0x9d8d9669, nil, "um" },
  [1219865] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Bastion:\n\nSubisci il $N1% di danni in meno mentre Scudo Benedetto è attivo.", nil, 0xe371efdf, nil, "um" },
  [1219866] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Reckoner:\n\nIl tuo talento Regolamento di Conti ora ha una probabilità del $N1% per punto talento di attivarsi quando blocchi.", nil, 0xf7d85cb2, nil, "um" },
  [1219867] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Ironclad:\n\nIl tuo Blessing of Sanctuary, se lanciato su te stesso, aumenta anche del $N1% tutte le caratteristiche.", nil, 0xb089c840, nil, "um" },
  [1219868] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Guardian:\n\nShield of the Righteous rende istantanea la tua prossima Luce Sacra. Se lanciata su te stesso, restituisce il $N1% del suo costo in mana e non è influenzata da Protezione della Luce.", nil, 0x29738ef7, nil, "um" },
  [1219869] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Peacekeeper:\n\nAumenta al $N1% la probabilità che gli alleati attivino il tuo Judgement of Light o Judgement of Wisdom.", nil, 0x2d7175c3, nil, "um" },
  [1219871] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Exemplar:\n\nOgni volta che Lampo di Luce, Luce Sacra o Faro di Luce curano un bersaglio fino alla salute piena, curi anche tutti i membri del suo gruppo di $N1 salute.", nil, 0x31595f8b, nil, "um" },
  [1219872] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Inquisitor:\n\nAumenta del $N1% la probabilità di critico di Folgore Sacra.", nil, 0xf8fc7d11, nil, "um" },
  [1219873] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Sovereign:\n\nAumenta del $N1% i danni inflitti dalla tua Consacrazione.", nil, 0xe578c6c3, nil, "um" },
  [1219874] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Dominus:\n\nQuando non sei tu il bersaglio del tuo Faro di Luce, anche il bersaglio del tuo Faro di Luce viene curato del $N1% dei danni che infliggi con Consacrazione, Esorcismo, Folgore Sacra, Ira Sacra e Martello dell'Ira.", nil, 0x4253c983, nil, "um" },
  [1219875] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Vindicator:\n\nRiduce del $N1% il tempo di recupero di Luce Divina.", nil, 0x0a2aa45f, nil, "um" },
  [1219876] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Altruist:\n\nLe tue cure sul bersaglio del tuo Faro di Luce curano anche il bersaglio amico ferito più vicino del $N1% di tale quantità.", nil, 0x68861e5c, nil, "um" },
  [1219877] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Arbiter:\n\nI tuoi Judgement of Light e Judgement of Wisdom conferiscono anche gli effetti di Giudizio del Crociato.", nil, 0x9db1e989, nil, "um" },
  [1219878] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Sealbearer:\n\nSigillo del Comando, Sigillo della Rettitudine, Seal of Martyrdom e Luce Solare infliggono il $N1% di danni in meno, ma ora persistono per $N2 s dopo che hai lanciato un altro sigillo, o finché non ne lanci un terzo. I tuoi Giudizi ora possono attivare più sigilli, se sono attivi.", nil, 0x66204e45, nil, "um" },
  [1219879] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Justicar:\n\nAumenta del $N1% i danni inflitti dai tuoi Giudizi offensivi e i tuoi Giudizi non consumano più i Sigilli sul bersaglio. I tuoi Giudizi ora possono attivare più Sigilli, se attivi.", nil, 0xfab12449, nil, "um" },
  [1219880] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Judicator:\n\nRiduce il tempo di recupero di Giudizio di $D1, ma riduce del $N2% i danni inflitti dai tuoi Giudizi.", nil, 0x4e512e5b, nil, "um" },
  [1219881] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Ascendant:\n\nIl tuo Giudizio aumenta i danni da sacro del $N1% per $D1, effetto che si accumula fino a $N3 volte.", nil, 0xf0c82a56, nil, "um" },
  [1219882] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Retributor:\n\nAumenta del $N1% i danni di Assalto del Crociato.", nil, 0x1b794919, nil, "um" },
  [1219883] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Excommunicator:\n\nI tuoi attacchi base con armi da mischia a due mani aumentano i danni del tuo prossimo Esorcismo lanciato entro $D1 del $N2%. Si accumula fino a $N3 volte.", nil, 0x3feea6a8, nil, "um" },
  [1219884] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Lightbringer:\n\nAumenta del $N1% i danni inflitti dal tuo incantesimo Folgore Sacra.", nil, 0x9dac3aaf, nil, "um" },
  [1219885] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Exile:\n\nRiduce il tempo di recupero di Esorcismo di $D1 e ne aumenta i danni inflitti del $N2%.", nil, 0x49e77c8f, nil, "um" },
  [1219886] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Templar:\n\nCon un'arma a una mano equipaggiata, Assalto del Crociato ora scatena l'effetto di Giudizio dei tuoi sigilli, ma non consuma il sigillo.", nil, 0xbf03dfa5, nil, "um" },
  [1219887] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Windwalker:\n\nAumenta del $N1% la tua velocità d'attacco per i tuoi prossimi $N2 colpi dopo aver parato, schivato o bloccato.", nil, 0xae1e61ed, nil, "um" },
  [1219888] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Shield Master:\n\nLe tue parate e schivate attivano anche l'abilità della runa Maestria nello Scudo.", nil, 0x0504a004, nil, "um" },
  [1219889] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Totemic Protector:\n\nIl tuo Totem della Pelle di Pietra riduce anche del $N1% i danni fisici subiti e il tuo Windwall Totem riduce anche del $N2% i danni magici subiti.", nil, 0x0b18bf10, nil, "um" },
  [1219890] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Shock-Absorber:\n\nLa tua Folgore del Fuoco aumenta anche del $N1% la probabilità di blocco per $D1 o finché non blocchi un attacco.", nil, 0xac5cd6ca, nil, "um" },
  [1219891] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Spiritual Bulwark:\n\nOgni volta che blocchi, il valore di blocco aumenta del $N1% dei tuoi danni magici per $D1, effetto che si accumula fino a $N3 volte.", nil, 0xc2b0eddc, nil, "um" },
  [1219892] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Maelstrombringer:\n\nOgni volta che blocchi un attacco, hai una probabilità del $N1% di attivare la tua runa Arma del Maelstrom.", nil, 0x98ad705b, nil, "um" },
  [1219893] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Lavawalker:\n\nInfliggere danni a un bersaglio con Assalto della Tempesta, Getto di Lava o Detonazione Fusa riduce anche del $N1% tutti i danni che subisci per $D1.", nil, 0xfa020d01, nil, "um" },
  [1219894] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the True Alpha:\n\nQuando lanci Spirit of the Alpha su te stesso, aumenta anche del $N1% la tua salute, del $N2% la minaccia che generi e del $N3% tutti i danni che infliggi.", nil, 0x598d83ec, nil, "um" },
  [1219895] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Totemkeeper:\n\nIl raggio dei tuoi totem che hanno effetto sui bersagli amici aumenta a $N1 m.", nil, 0x26b268a9, nil, "um" },
  [1219896] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Ancestors:\n\nDopo aver lanciato Ondata di Cura, Ondata di Cura Inferiore o Marea Gelida, hai una probabilità del $N1% di ottenere mana pari al $N2% del costo base dell'incantesimo.", nil, 0x18780f59, nil, "um" },
  [1219897] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Spiritweaver:\n\nLa tua Ondata di Cura ora rimbalza su altri bersagli vicini. Ogni rimbalzo riduce del $N1% l'efficacia della cura, e l'incantesimo rimbalza su un massimo di $N2 bersagli aggiuntivi.", nil, 0xcc0088f5, nil, "um" },
  [1219898] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Waterwalker:\n\nI tuoi colpi critici non periodici di danno e di cura ora hanno una probabilità del $N1% di attivare il tuo Scudo d'Acqua, senza consumarne una carica né attivarne il tempo di recupero.", nil, 0x8ff1a2e1, nil, "um" },
  [1219899] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Stormtender:\n\nLa tua Catena di Fulmini ora cura anche il bersaglio del tuo Scudo di Terra più recente del $N1% dei danni inflitti.", nil, 0xaf285f89, nil, "um" },
  [1219900] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Elemental Seer:\n\nAumenta del $N1% le cure di Catena di Guarigione e i danni di Catena di Fulmini.", nil, 0x9ad749dc, nil, "um" },
  [1219901] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Vitalist:\n\nLa tua Marea Gelida aumenta di un ulteriore $N1% la quantità curata da Catena di Guarigione.", nil, 0xac47edcc, nil, "um" },
  [1219902] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Spirithealer:\n\nRiduce il tempo di lancio di Catena di Guarigione di $D1.", nil, 0x62a088c4, nil, "um" },
  [1219904] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Chieftain:\n\nIl tuo talento Raffica di Colpi aumenta la tua velocità d'attacco di un ulteriore $N1%.", nil, 0x15deb29a, nil, "um" },
  [1219905] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Furycharged:\n\nLa tua probabilità di attivare Folgore Statica aumenta del $N1% (del $N2% se combatti con due armi).", nil, 0xde6f8cb0, nil, "um" },
  [1219906] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Stormbreaker:\n\nAumenta del $N1% i danni con la mano primaria inflitti dal tuo Assalto della Tempesta.", nil, 0x5d83820c, nil, "um" },
  [1219907] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Tempest:\n\nMentre Folgore Statica è incisa, il tuo Scudo di Fulmini ottiene una carica ogni volta che colpisci un bersaglio con Dardo Fulminante o Catena di Fulmini, fino a un massimo di $N1 cariche. Inoltre, mentre Folgore Statica è incisa, il tuo Scudo di Fulmini può infliggere danni critici.", nil, 0xfd19cb21, nil, "um" },
  [1219908] = { "Infondi in modo permanente nei tuoi spallacci la Soul of the Seismic Smasher:\n\nAumenta del $N1% i danni di Assalto della Tempesta e Sferzata Lavica. L'effetto aumenta al $N2% se usi un'arma a due mani.", nil, 0x9f9f5f7a, nil, "um" },
  [1219957] = { "Dopo aver cambiato postura, il costo in rabbia della tua prossima abilità offensiva si riduce di $N1.", nil, 0xc539fdf3, nil, "um" },
  [1219958] = { "Per $D1 dopo aver lasciato una postura, puoi usare le abilità che la richiedono come se fossi ancora in quella postura.", nil, 0xc53a0004, nil, "um" },
  [1219960] = { "Per i primi $D1 dopo aver attivato una postura, puoi ottenere un beneficio aggiuntivo:\n\nPostura da Battaglia/Gladiator Stance: danni inflitti aumentati del $N2%.\n\nPostura da Berserker: probabilità di critico aumentata del $N3%.\n\nPostura da Difesa: danni fisici subiti ridotti del $N4%.", nil, 0xc53a827a, nil, "um" },
  [1219962] = { "I colpi critici di Dominazione riportano al massimo la durata di Squartamento sul tuo bersaglio.", nil, 0xd6e870af, nil, "um" },
  [1219964] = { "Le tue abilità Assalto Eroico, Contusione e Dominazione infliggono il $N1% di danni in più.", nil, 0xd6e8f4b8, nil, "um" },
  [1219966] = { "I tuoi colpi di Contusione azzerano il tempo di recupero residuo delle abilità Assalto Mortale, Sete di Sangue e Colpo di Scudo.", nil, 0xd6e8f4b9, nil, "um" },
  [1219972] = { "Aumenta l'indice di blocco con lo scudo di $N1.", nil, 0xc539fd73, nil, "um" },
  [1219974] = { "Ottieni $N1 rabbia aggiuntiva ogni volta che subisci danni o infliggi danni con l'attacco automatico.", nil, 0xc539fd74, nil, "um" },
  [1219976] = { "Aumenta di un ulteriore $N1% tutta la minaccia che generi in Postura da Difesa e del $N2% tutti i danni che infliggi in Gladiator Stance.", nil, 0xc539fdf2, nil, "um" },
  [1219978] = { "Ottieni $N1 rabbia ogni volta che pari o che uno dei tuoi attacchi viene parato.", nil, 0xd6e8702f, nil, "um" },
  [1219980] = { "Rivincita ti conferisce anche Raffica di Colpi, che aumenta la tua velocità d'attacco del $N1% per i prossimi $N2 colpi.", nil, 0xd6e87031, nil, "um" },
  [1219982] = { "Quando il tuo bersaglio para un attacco, esegui istantaneamente una Reazione contro di lui che infligge il $N1% dei danni dell'arma. Reazione non può essere schivata, bloccata o parata, ma può verificarsi solo una volta ogni $D1 per bersaglio.", nil, 0xd6e87033, nil, "um" },
  [1219988] = { "Riduce il tempo di recupero di Colpo di Scudo di $D1.", nil, 0xd6e97bcd, nil, "um" },
  [1219990] = { "Riduce il tempo di recupero di Rabbia del Sangue di $D1 mentre sei in Gladiator Stance.", nil, 0xd6e97bce, nil, "um" },
  [1219994] = { "Finta conferisce anche Elusione per $D1, riducendo del $N2% tutti i danni subiti dagli attacchi ad area dei non giocatori.", nil, 0xc5393356, nil, "um" },
  [1219996] = { "Aumenta del $N1% il bonus ai danni critici dei tuoi veleni.", nil, 0xc53933d9, nil, "um" },
  [1219998] = { "Le tue mosse risolutive hanno una probabilità del $N1% per punto combo di azzerare il costo in energia della tua prossima abilità.", nil, 0xc5393457, nil, "um" },
})
